#!/usr/bin/env python3
# reserve_L13b.py — 새 과 L13b(안뜰의 싸움 · 세계 s13 의 b) — 면역 세계 「성 방어전」의 둘째 장(식세포 · 비만세포와 염증 · 인터페론 · RNAi · 보체 · 디펜신)
import json
P = '/tmp/b2/tools/hooks.json'
txt = open(P, encoding='utf-8').read(); d = json.loads(txt)
assert json.dumps(d, ensure_ascii=False, indent=1) == txt
R = d['_심볼예약']
B = '[2026-11-14 새 과 L13b]'
new = {
 '흰 덩이 셋 — 몸에서 뻗은 흰 팔로 세균을 감쌈 / 배의 둥근 창 속 비눗방울에 갇힌 세균 / 레몬 뜬 초록 물과 맞붙은 땅콩 꼴 방울 속 × 눈 세균': f'식세포작용 3단계(흡입 → 식포 → 리소좀 융합 · 분해) 전용 {B} — L13b s2(왼쪽부터 한 마리가 먹는 차례). 흰 팔 = 위족(몸을 늘인 팔 — 【풍선 벽이 살구색 줄을 품고 팔처럼 불룩 뻗음】(아메바 운동)과 뜻이 같은 계열이되 줄 · 움직임 선이 없다) · 비눗방울 = 막 주머니(【비눗방울에 싸인 큰 파란 공】 소낭과 같은 문법) · 레몬 뜬 초록 물 = 리소좀(【레몬 뜬 초록 물 구덩이】 그대로). ⚠ 배의 창은 「세탁기 창」으로도 읽힌다(일치 검사) — 글이 「배의 둥근 창」이라 부른다.',
 '작은 흰 덩이(큰 흰 덩이처럼 둥근 흰 몸 · 몸집이 작다)': f'단핵구(자라서 대식세포) 전용 {B} — L13b s1(먹는 셋 = 큰 흰 덩이 · 파리채 경비 · 작은 흰 덩이) · s9(보체에 젖은 세균을 들고 입맛 다심 = 옵소닌화된 것을 먹는 식세포). 큰 흰 덩이 = 대식세포(L13a 의 입 벌린 덩이).',
 '배 불룩한 뚱보 흰 옷 경비(눈 질끈 · 손바닥 펴 세균을 막음 · 불붙은 성냥 한 움큼)': f'비만세포(식균작용을 하지 않음 · 히스타민 등 매개물질) 전용 {B} — L13b s3 · s4(성냥불 바로 위의 호스가 부푼다) · s9(보체 물줄기를 무릎에 맞고 성냥을 한 움큼 켬 = 염증 증폭). 뚱뚱(비만) = 비만세포 · 성냥 = 【불붙은 성냥】(히스타민). ⚠ 성냥은 물줄기에서 먼 쪽 손에 — 물줄기가 성냥 곁으로 오면 「물이 불을 끈다」로 읽혔다(일치 검사 10회) · 호스에서 새는 물도 불에 닿지 않게 불꽃 끝을 호스 아래 36 px 로.',
 '성냥불 바로 위에서 볼록 부푼 진홍 호스(앞면의 세로 틈 셋에서 물이 줄줄 · 방울방울)': f'히스타민 → 혈관 확장 · 모세혈관 투과성 증가 전용 {B} — L13b s4 · s5. 진홍 호스 = 혈관(L46 의 호스 문법 — 【집 제 벽을 따라 내려가는 가는 진홍 호스】(관상동맥) · 【호스를 젖은 수건처럼 비트는 근육질 사내】(엔도텔린)과 같은 재료). 부풂 = 확장 · 틈으로 새는 물 = 혈장이 조직으로(투과성 ↑).',
 '진홍 호스의 타원 구멍으로 상반신을 비집고 나와 파리채를 치켜든 흰 옷 경비': f'호중구가 혈관 벽을 빠져나와 싸움터에 도착(유출) 전용 {B} — L13b s5(염증 순서의 셋째). 【흰 옷 경비】(L46e#6 「진홍 호스 벽을 빠져나가는 경비」)와 같은 뜻 — 이 세계에서는 부푼 자리 곁의 구멍.',
 '지쳐 대자로 뻗은 흰 옷 경비 둘(소용돌이 눈 · 빼문 혀 · 꽂힌 파리채 둘) + × 눈 초록 세균들이 든 누르스름한 웅덩이': f'고름(농 — 죽은 호중구 · 죽은 세균 · 부서진 조직) 전용 {B} — L13b s5(염증 순서의 끝). ⚠ 【기둥 위 감시 카메라(… 노란 기름 웅덩이)】(CCK · 지방)와 빛깔(초록 기 도는 누르스름한 크림 — 처음의 진한 노랑은 「노른자 · 기름」으로 읽혀 `pus_tint()` 로 바꿨다)과 속(쓰러진 경비)으로 가른다. 독자 첫인상은 여전히 「기름 · 늪 · 토사물 웅덩이에 쓰러진 사람들」 — 이름(고름)은 투어가 붙인다.',
 '끝이 뾰족한 나무 가시가 박혀 둥글게 퉁퉁 붓고 새빨갛고 김 나는 손가락(받쳐 들고 우는 주민)': f'염증의 4징후(발적 · 열감 · 부종 · 통증) 전용 {B} — L13b s6. 가시 = 국소 염증의 원인(캠벨의 그림). 【기름병을 짜 넣은 별 틀 · 날아가는 노란 별 · 빨갛게 부은 손】(프로스타글란딘)의 부은 손과 같은 뜻 계열(염증). ⚠ 처음의 부은 엄지발가락은 Gemini 가 「통풍」 발로 그렸다(L17c s10 통풍과 겹침) → 손가락 · ⚠ 깎은 연필 꼴의 가시는 「연필 · 막대」로 읽혔다 → 원뿔 끝을 떼고 가는 나뭇조각으로(`splinter()`).',
 '앞벽을 뗀 집(안에 망토 두른 이) — 밖에서 벽의 인터폰 수화기에 외치는 주민 → 판 윗머리의 전선 → 이웃 집 확성기 → 창에 판자를 대는 이웃': f'인터페론(감염 세포가 분비 → 이웃 세포가 항바이러스 채비 · 바이러스를 직접 막지 않음) 전용 {B} — L13b s7. 인터폰 = 【집 벽에 걸린 회색 인터폰】(인터페론) · 판자로 창 막기 = 이웃의 방어 준비 · 망토는 집 안에 그대로 = 직접 막지 않음. ⚠ 앞벽을 뗀 집은 【앞벽을 뜯은 이웃 동물 집】(심장의 방 수)과 다르다 — 방 하나 · 안에 바이러스와 효소 둘.',
 '깍둑썰기 기계(격자 칼날 상자 + 위의 누름 손잡이 — 종이 파쇄기 꼴)가 쏟아 내는 짧은 흰 종이 토막': f'Dicer(이중가닥 RNA 를 짧은 토막으로 자름) 전용 {B} — L13b s8(감염된 집 안 탁자). 다이서 = 깍둑썰기(dice). 독자 첫인상은 「종이 파쇄기 · 압착기」 — 하는 일(종이를 짧게 썬다)은 같다.',
 '흰 소용돌이 껍데기를 진 주황 문어(집낙지 · 아르고나우타) — 짧은 종이 토막을 쥐고 긴 두루마리를 찢음': f'Argonaute(짧은 RNA 를 길잡이로 표적 RNA 분해) 전용 {B} — L13b s8. 효소 이름이 집낙지(Argonauta)에서 왔다. ⚠ 보라 문어(리보솜 빛 — 【보라 리보솜】)가 아니라 주황 · 흰 껍데기.',
 '저수지에서 뿜는 물줄기 셋 — 뚱보 경비의 무릎에 철썩 / 작은 흰 덩이가 든 세균을 흠뻑 적심 / 세균 몸의 구멍을 꿰뚫고 지나감': f'보체의 세 결과(염증 증폭 · 옵소닌화 · 막공격복합체 MAC) 전용 {B} — L13b s9 · s10. 물길 셋 → 한 저수지 = 세 경로(고전 · 대체 · 렉틴)가 C3 에서 만남(옛 s13p03#0). 물줄기는 PIL(`jet()` — 양쪽 테가 따로 출렁이고 끝에서 물방울로 끊김 · 테는 짙은 파랑). ⚠ 고른 굵기 · 검은 테 · 매끈한 줄기는 「파란 관 · 호스 · 리본」, 보 쪽을 넓힌 줄기는 「저수지를 가리키는 화살」로 읽혔다(일치 검사 1 ~ 8회) · 줄기 둘은 보 윗머리 왼쪽 끝에서 위 · 아래로 갈라지고 셋째는 보 오른쪽 돌 벽의 검은 틈에서.',
 '몸 가운데 둥근 구멍이 뚫리고 그 구멍으로 물줄기가 지나가는 초록 세균(구멍 둘레가 쭈글쭈글)': f'막공격복합체(MAC — 보체 여럿이 이어 붙어 막에 구멍 → 용해 · 인터페론이 아니다) 전용 {B} — L13b s10(옛 s13p03#1 · IM-019 · 020). 구멍은 침입자의 몸에 — 옛 판은 성벽(제 몸)에 뚫었다. ⚠ 구멍에 바탕만 비치면 「흰 반창고 · 흰 자국」, 구멍 속에 물줄기 끝만 비치면 「눈알」로 읽혔다(일치 검사 1 · 9 · 10회) → 물줄기가 구멍을 지나 반대쪽으로 빠지게 · 구멍 안벽에 짙은 초록 초승달(`hole_wall()`).',
 '만년필(금빛 펜촉)로 초록 세균을 콕 찌르는 달팽이 · 화분의 분홍 튤립(줄기에서 뻗은 가는 초록 팔로 쥠)': f'디펜신(척추동물만이 아니라 무척추동물 · 식물에도 있는 항균 펩타이드 — 막에 구멍) 전용 {B} — L13b s11. 디-펜-신 = 펜 · 달팽이 = 무척추(연체 — 【구리 냄비를 진 달팽이】와 같은 동물) · 튤립 = 식물. ⚠ 【벽에 걸린 샤프펜슬】(샤가프) · 【사람 키만 한 빨간 매직펜】(L10c 교정)과 물건(검은 만년필 · 금빛 펜촉)으로 가른다. ⚠ 카드 IM-021 의 「보체 C9 과 상동」은 틀림(C9 과 닮은 것은 퍼포린) — 투어가 바로잡는다.',
}
for k, v in new.items():
    assert k not in R, k
    R[k] = v
def add(key, note):
    v = R[key]; assert isinstance(v, str), key
    R[key] = v + ' ' + note
add('흰 옷 경비', f'★ {B} 성 세계 L13b — 세균을 샌드위치처럼 베어 문 파리채 경비(호중구 = 식세포 · s1) · 진홍 호스의 구멍으로 비집고 나오는 경비(유출 · s5) · 누르스름한 웅덩이에 뻗은 경비 둘(고름 · s5) · 배 불룩한 뚱보 경비(비만세포 — 먹지 않음 · 성냥 · s3). 모두 가슴에 붉은 리본 배지.')
add('불붙은 성냥', f'★ {B} L13b 뚱보 흰 옷 경비(비만세포)가 치켜든 한 움큼 = 히스타민 — 그 바로 위의 진홍 호스(혈관)가 부풀고 샌다. 성냥은 물줄기에서 먼 쪽 손에(물 = 끄는 것).')
add('집 벽에 걸린 회색 인터폰(수화기 · 꼬불꼬불한 줄)', f'★ {B} L13b s7 — 앞벽을 뗀 집의 오른벽 바깥에 앞모습 판(PIL — L13a 의 판과 같은 회색 · 스피커 홈 · 빈 수화기 걸이) · 주민이 수화기를 들고 외친다(꼬불줄 = 판의 걸이에서) · 판 윗머리의 전선 → 이웃 집 확성기. Gemini 가 옆벽에 옆모습으로 그린 것(수화기가 걸린 채)은 지웠다.')
add('돌로 두른 도랑 끝을 막은 나무 판자 보(洑) + 넘쳐 고인 물', f'★ {B} L13b s9 — 돌 테두리 물길 셋 → 저수지 하나(보가 앞을 막음) → 물줄기 셋(【저수지에서 뿜는 물줄기 셋】). 도랑 · 세균은 L13a 의 조각을 올려 같은 꼴로 다시 그렸다(U9R).')
add('레몬 뜬 초록 물 구덩이(한 겹 천)', f'★ {B} L13b s2 셋째 흰 덩이의 배 창 속 — 레몬 조각 뜬 초록 물이 세균 방울과 맞붙음 = 리소좀 융합(같은 뜻).')
add('비눗방울에 싸인 큰 파란 공', f'★ {B} L13b s2 둘째 흰 덩이의 배 창 속 비눗방울에 갇힌 세균 = 식포(막 주머니 — 같은 문법).')
add('웃는 초록 알약 세균(얼굴 · 팔다리)', f'★ {B} 성 세계 L13b — 팔에 안기고 · 배 속 방울에 갇히고 · 베어 물리고 · 손바닥에 막히고 · 물에 젖고 · 몸에 구멍이 뚫리고 · 펜에 찔리는 초록 알약(모두 배지 없음 · 화난 / 놀란 / × 눈). 빛깔은 `regreen()` 으로 L13a 세균의 초록에 맞춘다(Gemini 가 따라 그리면 회녹 · 올리브로 바랬다).')
add('붉은 리본 배지(로제트 — 둥근 붉은 꽃 + 금빛 가운데 + 리본 꼬리 둘)', f'★ {B} L13b 열둘 — 흰 덩이 넷(큰 셋 · 작은 하나) · 흰 옷 경비 다섯 · 주민 셋(가시 박힌 이 · 수화기 든 이 · 판자 대는 이웃). 배지 없는 얼굴 = 초록 세균 · 망토 두른 이(침입자) · 주황 문어(효소 — 세포가 아니다) · 달팽이 · 튤립(성 밖의 다른 생물). ⚠ 흰 덩이의 배지를 몸 가장자리에 달면 「떠 있다」로 읽혔다 — 테 안쪽으로.')
add('망토 두른 사람 + 품에 안은 흰 종이 두루마리', f'★ {B} L13b s7 · s8 — 앞벽을 뗀 집 안에 들어앉은 망토(감염된 세포 속 바이러스) · 그 곁 탁자의 깍둑썰기 기계(Dicer)와 집낙지(Argonaute).')
add('기름병을 짜 넣은 별 틀 · 날아가는 노란 별 · 빨갛게 부은 손', f'★ {B} L13b s6 가시 박혀 붓고 빨갛고 김 나는 손가락 = 염증 4징후(같은 뜻 계열 — 부은 손 = 염증).')
add('앞벽을 뜯은 이웃 동물 집(방 수 · 벽)', f'★ {B} L13b 앞벽을 뗀 오두막(방 하나 · 망토 · 깍둑썰기 기계 · 집낙지) = 감염된 세포의 속 — 동물 집(심장의 방 수)과 다르다.')
add('구리 냄비를 진 달팽이 · 거미의 파란 피', f'★ {B} L13b s11 만년필 든 달팽이 = 무척추동물에도 디펜신(달팽이 = 연체 · 같은 동물).')
open(P, 'w', encoding='utf-8').write(json.dumps(d, ensure_ascii=False, indent=1))
print('예약', len(R), '· 새로', len(new))
